#include "study_support.h"
extern "C" int study_check(const char*path,double*metrics){try{std::ifstream file(path,std::ios::binary|std::ios::ate);auto size=file.tellg();if(size<0||size%8)throw std::runtime_error("artifactsize");std::vector<double>v(size/8);file.seekg(0);file.read((char*)v.data(),size);if(!file)throw std::runtime_error("shortartifact");size_t pos=0;double ma=0,mr=0,ind=0;auto get=[&](){return v.at(pos++);};auto exact=[&](double x){double z=get();if(memcmp(&z,&x,8))throw std::runtime_error("exactfixture/transpose/member/trace/guard");};auto near=[&](double x){double z=get();double d=fabs(z-x),r=x?d/fabs(x):0;ma=std::max(ma,d);mr=std::max(mr,r);if(!std::isfinite(z)||d>1e-6+1e-6*fabs(x))throw std::runtime_error("numericaloracle");return z;};auto cs=cases();exact(3);for(auto&c:cs){for(int h:{c.n,c.f,c.lo,c.hi,c.restarts})exact(h);for(float x:c.x)exact(x);}for(auto&c:cs){int bestk=0,bestloop=0;float bestrm=std::numeric_limits<float>::max();for(int k=c.lo;k<=c.hi;k++){exact(k);for(int a=0;a<c.f;a++)for(int i=0;i<c.n;i++)exact(c.x[i*c.f+a]);std::vector<int>initial(c.n);for(int i=0;i<c.n;i++)initial[i]=i;int left=c.n;for(int restart=0;restart<c.restarts;restart++){exact(restart);std::vector<float>cent(k*c.f);for(int j=0;j<k;j++){if(left<=0)throw std::runtime_error("sourceinitialunderflow");for(int a=0;a<c.f;a++)cent[j*c.f+a]=c.x[initial[j]*c.f+a];std::swap(initial[j],initial[left-1]);left--;}std::vector<int>prev(c.n,-1);int loop=0,iter=0,delta;do{exact(iter);for(float z:cent)exact(z);std::vector<int>mem(c.n);for(int i=0;i<c.n;i++){mem[i]=nearest(c.x,i,c.f,cent,k);double observed=get();if(observed!=mem[i])throw std::runtime_error("fullmembership");double best=std::numeric_limits<double>::infinity();int independent=0;for(int j=0;j<k;j++){double d=0;for(int a=0;a<c.f;a++){double z=double(c.x[i*c.f+a])-cent[j*c.f+a];d+=z*z;}if(d<best){best=d;independent=j;}}if(observed!=independent)throw std::runtime_error("Float64nearest/tiefirst");}auto old=cent;update(c,cent,mem,prev,delta);exact(delta);for(float z:cent)near(z);for(int j=0;j<k;j++){int count=0;std::vector<double>sum(c.f,0);for(int i=0;i<c.n;i++)if(mem[i]==j){count++;for(int a=0;a<c.f;a++)sum[a]+=c.x[i*c.f+a];}if(count)for(int a=0;a<c.f;a++){double e=fabs(cent[j*c.f+a]-sum[a]/count);ind=std::max(ind,e);if(e>2e-6)throw std::runtime_error("Float64centroid");}}iter++;}while(delta>.001f&&(loop++<500));exact(iter);float rms=rmse(c,cent);near(rms);int truncated=rms;exact(truncated);if(truncated<bestrm){bestrm=truncated;bestk=k;bestloop=restart;}for(float z:cent)near(z);} }exact(bestk);exact(bestloop);exact(bestrm);for(int g=0;g<512;g++)exact(-777.);}if(pos!=v.size())throw std::runtime_error("trailingartifact");metrics[0]=ma;metrics[1]=mr;metrics[2]=ind;return 0;}catch(std::exception&e){fprintf(stderr,"KMEANS_CHECK_FAIL %s\n",e.what());return 1;}}
